<?php require 'includes/db.php';require 'includes/auth.php';if(logged_in()){header('Location:index.php');exit;}$error='';if($_SERVER['REQUEST_METHOD']==='POST'){$email=strtolower(trim($_POST['email']??''));$pass=$_POST['password']??'';$s=$pdo->prepare("SELECT * FROM users WHERE email=?");$s->execute([$email]);$u=$s->fetch(PDO::FETCH_ASSOC);if($u&&password_verify($pass,$u['password_hash'])){session_regenerate_id(true);$_SESSION['user_id']=$u['id'];header('Location:index.php');exit;} $error='Invalid email or password.';}?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Login - Expense Tracker</title><link rel="stylesheet" href="assets/auth.css"></head><body><div class="auth"><div class="logo">₹</div><h1>Welcome back</h1><p>Sign in to your expense tracker</p><?php if($error):?><div class="error"><?=h($error)?></div><?php endif;?><form method="post"><label>Email<input type="email" name="email" required autocomplete="email"></label><label>Password<input type="password" name="password" required autocomplete="current-password"></label><button>Login</button></form><p>New here? <a href="register.php">Create an account</a></p></div></body></html>